function startTest(enableDimming) {
            const overlay = document.getElementById('test-overlay');
            const box = document.getElementById('local-dimming-box');
            overlay.style.display = 'block';
            if (enableDimming) {
                box.style.display = 'block';
            } else {
                box.style.display = 'none';
            }
            if (document.documentElement.requestFullscreen) {
                document.documentElement.requestFullscreen();
            }
            // Hide HUD initially after 2s
            setTimeout(() => {
                document.getElementById('overlay-hud').style.opacity = '0';
            }, 2000);
        }
        function toggleHud() {
            const hud = document.getElementById('overlay-hud');
            hud.style.opacity = (hud.style.opacity === '1') ? '0' : '1';
        }
        function stopTest() {
            document.getElementById('test-overlay').style.display = 'none';
            document.getElementById('overlay-hud').style.opacity = '1';
            if (document.exitFullscreen) {
                document.exitFullscreen();
            }
        }
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') stopTest();
        });
